update RB_PASSWORD
set
    PWD_KEY = #{row.pwdKey,jdbcType=VARCHAR},            PWD_TYPE = #{row.pwdType,jdbcType=VARCHAR},            CLIENT_NO = #{row.clientNo,jdbcType=VARCHAR},            PASSWORD = #{row.password,jdbcType=VARCHAR},            PASSWORD_EFFECT_DATE = #{row.passwordEffectDate,jdbcType=TIMESTAMP},            PASSWORD_STATUS = #{row.passwordStatus,jdbcType=VARCHAR},            CHANGE_IND = #{row.changeInd,jdbcType=VARCHAR},            FAILURE_TIMES = #{row.failureTimes,jdbcType=INTEGER},            TRAN_TIMESTAMP = #{row.tranTimestamp,jdbcType=VARCHAR},            LAST_CHANGE_DATE = #{row.lastChangeDate,jdbcType=TIMESTAMP},            COMPANY = #{row.company,jdbcType=VARCHAR},            PREV_FAILURE_TIMES = #{row.prevFailureTimes,jdbcType=INTEGER},            DAY_FAILURE_TIMES = #{row.dayFailureTimes,jdbcType=INTEGER},            DAC_VALUE = #{row.dacValue,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{row.createTimestamp,jdbcType=VARCHAR}

update RB_PASSWORD
set
    PASSWORD = #{password,jdbcType=VARCHAR},            PASSWORD_EFFECT_DATE = #{passwordEffectDate,jdbcType=TIMESTAMP},            PASSWORD_STATUS = #{passwordStatus,jdbcType=VARCHAR},            CHANGE_IND = #{changeInd,jdbcType=VARCHAR},            FAILURE_TIMES = #{failureTimes,jdbcType=INTEGER},            TRAN_TIMESTAMP = #{tranTimestamp,jdbcType=VARCHAR},            LAST_CHANGE_DATE = #{lastChangeDate,jdbcType=TIMESTAMP},            COMPANY = #{company,jdbcType=VARCHAR},            PREV_FAILURE_TIMES = #{prevFailureTimes,jdbcType=INTEGER},            DAY_FAILURE_TIMES = #{dayFailureTimes,jdbcType=INTEGER},            DAC_VALUE = #{dacValue,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{createTimestamp,jdbcType=VARCHAR}        where PWD_KEY = #{pwdKey,jdbcType=VARCHAR}
  and PWD_TYPE = #{pwdType,jdbcType=VARCHAR}
  and CLIENT_NO = #{clientNo,jdbcType=VARCHAR}
